import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { t } from '../../common/t';
import { date } from '../../common/money';
import { confirm, purchase } from '../../common/api';
/**
 * /store/return/K-… — where PayPal sends the buyer back. It asks the server
 * to check with PayPal (never trusting the query string), then waits a little
 * for a subscription's activation to arrive.
 */
export default class ReturnPage extends Page {
  purchase = null;
  phase = 'checking';
  tries = 0;
  timer = 0;
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(extractText(t('forum.return.title')));
    const number = m.route.param('number');
    if (m.route.param('cancelled')) {
      this.phase = 'cancelled';
      return;
    }
    confirm(number).then(({
      data
    }) => this.settle(data), () => {
      this.phase = 'failed';
      m.redraw();
    });
  }
  onremove(vnode) {
    super.onremove(vnode);
    clearTimeout(this.timer);
  }
  settle(p) {
    this.purchase = p;
    if (p.status === 'active' || p.status === 'canceled') {
      this.phase = 'done';
      // What they bought may have changed what they can see.
      app.store.find('users', String(app.session.user.id()));
    } else if (this.tries++ < 15) {
      this.phase = 'waiting';
      this.timer = window.setTimeout(() => purchase(p.number).then(({
        data
      }) => this.settle(data)), 2000);
    } else {
      this.phase = 'waiting';
    }
    m.redraw();
  }
  view() {
    return m(PageStructure, {
      className: "KioskReturnPage",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "KioskReturn"
    }, this.body()));
  }
  body() {
    const p = this.purchase;
    switch (this.phase) {
      case 'checking':
        return [m(LoadingIndicator, {
          display: "block"
        }), m("p", null, t('forum.return.checking'))];
      case 'cancelled':
        return [m("h2", null, t('forum.return.cancelled_title')), m("p", null, t('forum.return.cancelled_text')), m(LinkButton, {
          className: "Button",
          href: app.route('kiosk.store')
        }, t('forum.return.back_to_store'))];
      case 'failed':
        return [m("h2", null, t('forum.return.failed_title')), m("p", null, t('forum.return.failed_text')), m(LinkButton, {
          className: "Button",
          href: app.route('kiosk.purchases')
        }, t('forum.purchases.title'))];
      case 'waiting':
        return [m(LoadingIndicator, {
          display: "block"
        }), m("h2", null, t('forum.return.waiting_title')), m("p", null, t('forum.return.waiting_text'))];
      default:
        return [m(Icon, {
          name: "fas fa-circle-check",
          className: "KioskReturn-icon"
        }), m("h2", null, t('forum.return.done_title', {
          product: p?.productName
        })), p?.periodEnd ? m("p", null, t(p.kind === 'recurring' ? 'forum.return.renews' : 'forum.return.until', {
          date: date(p.periodEnd)
        })) : m("p", null, t('forum.return.forever')), p?.unlocks.some(u => u.url) ? m("div", {
          className: "KioskReturn-links"
        }, p.unlocks.filter(u => u.url).map(u => m("a", {
          className: "Button Button--primary",
          href: u.url
        }, t('forum.return.go_to', {
          name: u.label
        })))) : null, m(LinkButton, {
          className: "Button",
          href: app.route('kiosk.purchases')
        }, t('forum.purchases.title'))];
    }
  }
}
flarum.reg.add('ernestdefoe-kiosk', 'forum/pages/ReturnPage', ReturnPage);